import {
  Component,
  Element,
  Event,
  type EventEmitter,
  Host,
  Method,
  Prop,
  State,
  Watch,
  h,
} from "@stencil/core";

import magneticMeta from "../../../plugins/icons/icons.magnetic.json";
import { iconsMap } from "../../utils/iconsmapping";
import { getCssRulesForSentiment } from "../../utils/sentiments";
import { addConstructedStyle } from "../../utils/browser";
import {
  getLibrary,
  unwatchIcon,
  watchIcon,
} from "../icon-library/icon-library-registry";
import { requestIcon } from "./request";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {Sentiment} from "../../common-types"

const parser = new DOMParser();

/**
 * @since 0.0.5
 * @status stable
 *
 * @description Icons are visual symbols used to communicate messages at a glance or convey what a user might be able to do in an interface. Icons bring the interface to life by visually communicating identity, capability, actions, status, and feedback.
 *
 * @part base - The component's base wrapper.
 */
@Component({
  tag: "hbr-icon",
  styleUrl: "icon.scss",
  shadow: true,
})
export class Icon {
  sheet: CSSStyleSheet = new CSSStyleSheet();
  @Element() host: HTMLHbrIconElement;

  @State() svg: string;

  /** Raw svg source code as string */
  @Prop({ reflect: false }) asset: string | (() => string);

  /** An external URL of an SVG file. */
  @Prop() src: string;

  /** Options to pass to the fetch request when fetching the icon from a URL. since 2.13.5 */
  @Prop() fetchOptions = {};

  /** The name of the icon to draw. */
  @Prop({ reflect: true }) name: string;

  /** Size of the icon, by default icons are sized relative to the current font size */
  @Prop() size: string;

  /** Width of the icon, takes priority over size and css font-size. Set this prop when width and height are not same.*/
  @Prop() width: string;

  /** Height of the icon, takes priority over size and css font-size. Set this prop when width and height are not same. */
  @Prop() height: string;

  /** An alternative description to use for accessibility. If omitted, the name or src will be used to generate it. */
  @Prop() label: string;

  /** A list of Colors for the paths*/
  @Prop() colors: Array<string>;

  /** The icons's sentiment. */
  @Prop({ reflect: true }) sentiment: Sentiment;

  /** The name of a registered custom icon library. */
  //If data-theme is null, or localStorage/getAttribute fails, hbr-theme-magnetic icons will be rendered.
  //@ts-ignore
  @Prop({ mutable: true }) library:
    | "hbr-theme-magnetic"
    | "phosphor"
    | "base"
    | string = "hbr-theme-magnetic";

  /** Retain static colors hardcoded in the svg file instead of replacing them with css properties by default */
  @Prop({ reflect: true }) staticColors = false;

  /** Emitted when the icon has loaded. */
  @Event({ eventName: "hbr-load" }) hbrLoad: EventEmitter;

  /** Emitted when the icon failed to load. */
  @Event({ eventName: "hbr-error" }) hbrError: EventEmitter<{
    status?: number;
  }>;

  defaultColors = [];
  defaultSecondaryColor = "";

  @Watch("name")
  @Watch("src")
  @Watch("library")
  @Watch("asset")
  handleChange() {
    this.setIcon();
  }

  @Watch("label")
  handleLabelChange() {
    this.setA11y();
  }

  connectedCallback() {
    watchIcon(this.host);
    this.setIcon();
    this.setA11y();
  }

  componentDidLoad() {
    this.setIcon();
  }

  componentDidRender() {
    this.setCssProperties();
  }

  disconnectedCallback() {
    unwatchIcon(this.host);
  }

  /** @internal Fetches the icon and redraws it. Used to handle library registrations. */
  @Method()
  async redraw() {
    this.setIcon();
  }

  setA11y() {
    const hasLabel = typeof this.label === "string" && this.label.length > 0;

    if (hasLabel) {
      this.host.setAttribute("role", "img");
      this.host.setAttribute("aria-label", this.label);
      this.host.removeAttribute("aria-hidden");
    } else {
      this.host.removeAttribute("role");
      this.host.removeAttribute("aria-label");
      this.host.setAttribute("aria-hidden", "true");
    }
  }

  verifyMap() {
    let name = "";
    if (iconsMap[this.name] && iconsMap[this.name][this.library]) {
      name = iconsMap[this.name][this.library];
    } else if (iconsMap[this.name] && !iconsMap[this.name][this.library]) {
      name = null;
    } else {
      name = this.name;
    }
    return name;
  }

  resolveIcon(registry, name) {
    return registry.resolver(name);
  }

  async setIcon() {
    const library = getLibrary(this.library);
    if (this.asset) {
      this.getFile(library, {
        ok: true,
        svg: typeof this.asset === "function" ? this.asset() : this.asset,
      });
      return;
    }
    let url = this.src;
    if (this.name && library) {
      //Check icon map.
      const _name = this.verifyMap();
      // resolve svg URL only when a src is not available
      if (_name && typeof url !== "string") {
        const iconAssetPath = getBootstrapConfig()?.iconAssetPath;
        if (iconAssetPath) {
          url = iconAssetPath + `${this.name}.svg`;
        } else {
          url = this.resolveIcon(library, _name);
        }
      }
      //Check JSON mapping to verify icon name is present
      //Before hitting the network.
      if (this.library === "hbr-theme-magnetic") {
        if (!magneticMeta.includes(_name)) {
          console.warn(`${_name} not found in current library ${this.library}`);
          return;
        }
      }
    }

    if (url) {
      try {
        const options = this.fetchOptions;
        const file = await requestIcon(url, options);
        if (file.ok && file.svg) {
          this.getFile(library, file);
        } else {
          if (this.name) {
            console.warn(
              `${this.name} not found in current library ${this.library}`
            );
          } else if (this.src) {
            console.warn("fail to find the external URL of an SVG file ");
          }
        }
      } catch {
        console.warn(`Error rendering icon file for ${this.name}`);
      }
    } else if (this.svg) {
      // If we can't resolve a URL and an icon was previously set, remove it
      this.svg = null;
    } else {
      if (this.name) {
        console.warn(
          `${this.name} not found in current library ${this.library}`
        );
      }
    }
  }
  getFile(library, file) {
    const doc = parser.parseFromString(file.svg, "text/html");
    const svg = doc.body.querySelector("svg");
    if (svg) {
      if (library?.mutator) {
        const payload = library.mutator(svg, this.staticColors);
        if (payload) {
          this.defaultColors = payload.colors;
          this.defaultSecondaryColor = payload.secondaryColor;
        }
      }
      this.svg = svg.outerHTML;
      this.hbrLoad.emit();
    } else {
      this.svg = "";
      this.hbrError.emit({ status: file.status });
    }
  }
  getPathSecondaryColor = (holder) => {
    if (this.defaultSecondaryColor) {
      const cascadingSecColorProperty = getComputedStyle(
        holder
      ).getPropertyValue("--path-secondary-color");
      const secondaryColor =
        !cascadingSecColorProperty && this.defaultSecondaryColor
          ? this.defaultSecondaryColor
          : null;
      if (secondaryColor) {
        holder.style.setProperty("--path-secondary-color", secondaryColor);
      }
    }
  };

  setCssProperties() {
    const holder: HTMLElement =
      this.host.shadowRoot.querySelector(".hbr_css--icon");
    this.getPathSecondaryColor(holder);
    const colors = this.colors ? this.colors : [];
    if (colors?.length) {
      colors.forEach((color, id) => {
        holder.style.setProperty(`--path-color-${id}`, color);
      });
    }
  }

  render() {
    /**
     * Ways of setting size in order of priority
     *  - @prop width: to set a width separate from height
     *  - @prop height: to set a height separate from width
     *  - @prop size: to set symmetrical width and height
     *  - @css font-size: current font-size, inherited from parent
     *  - @css width: to set a width separate from height
     *  - @css height: to set a height separate from height
     *  Logic: the svg file has a 100% width and height and fills its parent
     *  When width, height or size props are set, width and height of the host
     *  are derived from these props and set as inline style, without these
     *  props, width and height of the host is 1em.
     */
    const width = this.width || this.size || null;
    const height = this.height || this.size || null;
    const hostProps = {
      ...(width || height
        ? {
            style: {
              ...(width ? { width } : null),
              ...(height ? { height } : null),
            },
          }
        : null),
    };

    if (this.sentiment && this.host) {
      this.sheet.replaceSync(`
				:host {
					${getCssRulesForSentiment({
            sentiment: this.sentiment,
            type: "icon",
          })}
				}
			`);
      addConstructedStyle(this.host.shadowRoot, this.sheet);
    }

    return (
      <Host {...hostProps}>
        <div part="base" class="hbr_css--icon" innerHTML={this.svg} />
      </Host>
    );
  }
}
